              <div><strong>জরুরি হেল্পলাইন:</strong> <a href="tel:01966442769" style="font-family: var(--font-en); font-weight: 700; color: #075B3B; text-decoration:none;">০১৯৬৬-৪৪২৭৬৯</a></div>
